"""Author physical model, SQL and dictionary together. Artifact only; never connects to DB."""
import json,pathlib,re
R=pathlib.Path(__file__).resolve().parents[2];OUT=R/'docs/data/physical';OUT.mkdir(parents=True,exist_ok=True)
M=OUT/'migrations';M.mkdir(exist_ok=True)
tables=[]
def table(name,columns,checks=(),unique=(),refs=(),tenant=True,mutable=True,retention='workspace lifecycle'):
 common=['workspace_id text NOT NULL','id text NOT NULL',"created_at timestamptz NOT NULL DEFAULT now()"] if tenant else ['id text PRIMARY KEY',"created_at timestamptz NOT NULL DEFAULT now()"]
 if mutable:common+=['version bigint NOT NULL DEFAULT 1 CHECK (version > 0)','updated_at timestamptz NOT NULL DEFAULT now()']
 enum_fields={
  ('reviews','type'):['cash','duplicate','invalid','transfer','refund','quality','category','pending'],
  ('source_records','status'):['staged','invalid','duplicate','linked'],
  ('quote_observations','quality'):['fresh','stale','unknown'],
  ('agent_runs','intent'):['goal','plan','investigation'],
  ('messages','processing_kind'):['rule','single_tool','agent','scripted'],
  ('ops_sources','state'):['enabled','disabled','degraded'],
  ('ops_jobs','state'):['queued','running','failed','succeeded','paused'],
  ('ops_jobs','job_type'):['price_refresh','ingestion','sync','import','agent'],
  ('ops_accounts','state'):['active','suspended'],
  ('ops_releases','test_state'):['not_run','passed','failed'],
  ('ops_incidents','severity'):['info','warning','critical'],
  ('ops_incidents','state'):['open','resolved'],
  ('ops_audit','action'):['retry_job','disable_source'],
  ('ops_audit','result'):['succeeded','failed','denied'],
 }
 cols=[]
 for c in common+columns:
  field=c.split()[0]
  if (name,field) in enum_fields:c+=' CHECK ('+field+' IN ('+','.join("'"+x+"'" for x in enum_fields[name,field])+'))'
  if ' jsonb' in c:
   array_fields={'allowed_assets','rows','selected_row_ids','skip_months','confirmed_ids','device_health','evidence_refs','assumptions'}
   kind='array' if field in array_fields else 'object'
   c+=f" CHECK ({field} IS NULL OR (jsonb_typeof({field})='{kind}' AND octet_length({field}::text)<=262144))"
  if field in ['payload_digest','content_digest','file_digest','mapping_digest','digest']:c+=f" CHECK ({field} ~ '^[a-f0-9]{{64}}$')"
  cols.append(c)
 constraints=(['PRIMARY KEY (workspace_id,id)','FOREIGN KEY (workspace_id) REFERENCES fw.workspaces(id)'] if tenant else [])+list(checks)+['UNIQUE ('+x+')' for x in unique]
 if name=='devices':constraints.append("CHECK ((status='revoked')=(revoked_at IS NOT NULL))")
 if name=='ingestion_receipts':constraints += ["CHECK (state<>'posted' OR event_id IS NOT NULL)","CHECK (state<>'needs_review' OR review_id IS NOT NULL)"]
 relations=[]
 for field,parent in refs:
  constraints.append(f'FOREIGN KEY (workspace_id,{field}) REFERENCES fw.{parent}(workspace_id,id) DEFERRABLE INITIALLY DEFERRED');relations.append({'columns':['workspace_id',field],'target':parent,'targetColumns':['workspace_id','id']})
 tables.append({'name':name,'tenant':tenant,'mutable':mutable,'columns':[{'name':c.split()[0],'sql':c,'nullable':'NOT NULL' not in c and 'PRIMARY KEY' not in c,'meaning':c.split()[0].replace('_',' ')} for c in cols],'constraints':constraints,'relations':relations,'retention':retention})
table('identities',["email text NOT NULL UNIQUE CHECK (email ~ '^[^@]+@[^@]+[.]test$')",'display_name text NOT NULL','credential_hash text NOT NULL',"state text NOT NULL CHECK (state IN ('active','suspended','deleted'))"],tenant=False)
