 ('ops_previews',['subject_id text NOT NULL','action text NOT NULL','object_id text NOT NULL','expected_version bigint NOT NULL','reason_code text NOT NULL','digest text NOT NULL','token_digest text NOT NULL UNIQUE','expires_at timestamptz NOT NULL'],'24h'),
