model={'profile':'SYNTHETIC-ONLY','postgresMajor':16,'tables':tables,'indexes':[dict(zip(['name','table','columns','where','purpose'],x)) for x in indexes]}
(OUT/'physical-model.json').write_text(json.dumps(model,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
sql=['-- ARTIFACT ONLY. PostgreSQL 16+. Dedicated disposable synthetic database.','BEGIN;','CREATE SCHEMA fw;','REVOKE ALL ON SCHEMA fw FROM PUBLIC;']
for t in tables:
 sql+=['CREATE TABLE fw.'+t['name']+' (\n  '+',\n  '.join([c['sql'] for c in t['columns']]+t['constraints'])+'\n);']
for name,t,cols,where,purpose in indexes:
 sql+=['-- '+purpose,'CREATE '+('UNIQUE ' if 'unique' in name or name in ['binding_live','ops_replay'] else '')+'INDEX '+name+' ON fw.'+t+' ('+cols+')'+(' WHERE '+where if where else '')+';']
sql+=['ALTER TABLE fw.messages ADD FOREIGN KEY (workspace_id,agent_run_id) REFERENCES fw.agent_runs(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;','ALTER TABLE fw.messages ADD FOREIGN KEY (workspace_id,planning_draft_id) REFERENCES fw.planning_drafts(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;','COMMIT;']
(M/'001_synthetic_tables.sql').write_text('\n\n'.join(sql)+'\n',encoding='utf-8')
dictionary=['# Physical data dictionary — synthetic PostgreSQL','08/10/2026. Generated with physical-model.json and 001 by tools/handover/build_data.py; change the authored model definitions and regenerate together before first deployment. After migration execution, issue new migrations instead of editing historical checksums. Plaintext profile, never anti-Ops evidence. JSON payloads are schema-validated in the service against canonical v2; SQL checks only outer type/size.','All tenant PKs `(workspace_id,id)`; cross-object FKs carry workspace. Text IDs preserve frontend opaque IDs; UUID-shaped IDs are accepted, not required. `numeric(18,0)` VND integer; `numeric(28,8)` quantity/quotes. Instants timestamptz, business dates date. Versions bigint in DB but <=2^53-1 at JSON boundary.','For mutable tables service archives old row in version_history and increments version; financial_version increments only after financial projection changes. Read/draft/chat/receipt ACK do not automatically advance it.']
