for t in tables:
 dictionary+=['\n## '+t['name'],f"Boundary: {'workspace owner' if t['tenant'] else 'identity/public catalogue/ops service; grants explicit'}. Retention: {t['retention']}.",'| Column | PostgreSQL declaration | Nullable | Meaning |','| --- | --- | --- | --- |']
 for c in t['columns']:dictionary.append(f"| {c['name']} | `{c['sql']}` | {'yes' if c['nullable'] else 'no'} | {c['meaning']} |")
 dictionary+=['\nConstraints: '+ '; '.join('`'+c+'`' for c in t['constraints'])+'.']
 for rel in t['relations']:erd.append('  '+rel['target']+' ||--o{ '+t['name']+' : '+rel['columns'][1])
 for idx in model['indexes']:
  if idx['table']==t['name']:dictionary.append(f"Index `{idx['name']}` ({idx['columns']}): {idx['purpose']}; predicate {idx['where'] or 'all rows'}.")
(OUT/'data-dictionary.md').write_text('\n'.join(dictionary)+'\n',encoding='utf-8')
(OUT/'erd.mmd').write_text('\n'.join(erd)+'\n',encoding='utf-8')
(OUT/'erd.md').write_text('# Physical ERD — synthetic profile\n\n```mermaid\n'+'\n'.join(erd)+'\n```\n\nIdentity owner → workspaces; global instrument/profile → tenant holdings; ops metadata deliberately has no FK into finance. See [dictionary](data-dictionary.md).\n',encoding='utf-8')
print(json.dumps({'tables':len(tables),'indexes':len(indexes),'profile':'SYNTHETIC-ONLY'}))
